import static net.runelite.http.api.RuneLiteAPI.GSON;

public class InputStreamUtility
{
    public static <T> T load(InputStream input, Type type) throws IOException
    {
        try (Reader reader = new InputStreamReader(input, StandardCharsets.UTF_8))
        {
            return GSON.fromJson(reader, type);
        }
    }

    public static Map<Integer, NpcDefinition> loadById(InputStream input) throws IOException
    {
        Map<Integer, NpcDefinition> npcs = new LinkedHashMap<>();
        for (NpcDefinition npc : loadAllNpcs(input))
        {
            npcs.put(npc.getId(), npc);
        }
        return npcs;
    }

    public static HashMap<Integer, Integer> loadAllOffsets(InputStream input) throws IOException
    {
        Type type = new TypeToken<Map<Integer, Integer>>() {}.getType();
        return load(input, type);
    }

    public static List<NpcDefinition> loadAllNpcs(InputStream input) throws IOException
    {
        Type type = new TypeToken<List<NpcDefinition>>() {}.getType();
        return load(input, type);
    }

}

package com.example.Utilities;

import com.example.PetData;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

public class ModelUtility
{
    private static final int NPC_AMBIENT = 64;
    private static final int NPC_CONTRAST = 850;
    private static final int NPC_LIGHT_X = -30;
    private static final int NPC_LIGHT_Y = -50;
    private static final int NPC_LIGHT_Z = -30;

    private static ModelData createModel(Client client, ModelData... data)
    {
        return client.mergeModels(data);
    }

    private static ModelData createModel(Client client, int... data)
    {
        ModelData[] modelData = new ModelData[data.length];
        for (int i = 0; i < data.length; i++)
        {
            modelData[i] = client.loadModelData(data[i]);
        }
        return client.mergeModels(modelData);
    }

    public static Model provideModel(Client client, PetData petData)
    {
        int[] modelIDs = petData.getModelIDs();
        short[] recolorIDs = petData.getColorToReplace();
        short[] replaceRecolorIDs = petData.getColorToReplaceWith();

        ModelData[] modelDataArray = new ModelData[modelIDs.length];

        for (int i = 0; i < modelDataArray.length; i++)
        {
            modelDataArray[i] = client.loadModelData(modelIDs[i]);
        }

        ModelData modelData = createModel(client,modelDataArray);
        modelData.cloneVertices();

        if (recolorIDs != null && replaceRecolorIDs != null)
        {
            modelData.cloneColors();
            for (int i = 0; i < recolorIDs.length; i++)
            {
                modelData.recolor(recolorIDs[i],replaceRecolorIDs[i]);
            }
        }

        return modelData.light(petData.getAmbient()  + NPC_AMBIENT, petData.getContrast() + NPC_CONTRAST, NPC_LIGHT_X, NPC_LIGHT_Y, NPC_LIGHT_Z);
    }


}

package com.example.Utilities;

import com.example.PetObjectModel;
import net.runelite.api.AABB;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Renderable;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.geometry.SimplePolygon;
import net.runelite.api.model.Jarvis;
import net.runelite.client.callback.RenderCallback;

import java.util.function.BiPredicate;

public class RenderUtility {

    public static SimplePolygon calculateAABB(Client client, Model m, int jauOrient, int x, int y, int z, int zOff)
    {
        AABB aabb = m.getAABB(jauOrient);

        int x1 = aabb.getCenterX();
        int y1 = aabb.getCenterZ();
        int z1 = aabb.getCenterY() + zOff;

        int ex = aabb.getExtremeX();
        int ey = aabb.getExtremeZ();
        int ez = aabb.getExtremeY();

        int x2 = x1 + ex;
        int y2 = y1 + ey;
        int z2 = z1 + ez;

        x1 -= ex;
        y1 -= ey;
        z1 -= ez;

        float[] xa = new float[]{
                x1, x2, x1, x2,
                x1, x2, x1, x2
        };
        float[] ya = new float[]{
                y1, y1, y2, y2,
                y1, y1, y2, y2
        };
        float[] za = new float[]{
                z1, z1, z1, z1,
                z2, z2, z2, z2
        };

        int[] x2d = new int[8];
        int[] y2d = new int[8];

        Perspective.modelToCanvas(client,client.getTopLevelWorldView(),8, x, y, z, 0, xa, ya, za, x2d, y2d);
        return Jarvis.convexHull(x2d, y2d);
    }


    public static void conditionalHide(PetObjectModel pom, boolean shouldHide)
    {
        //should force the object to render far under the ground
        int hideZ = 1000;
        RuneLiteObject rlo = pom.getRlObject();
        if (shouldHide && rlo.getZ() != hideZ)
        {
            rlo.setZ(hideZ);
        }
        else if (!shouldHide && rlo.getZ() == hideZ)
        {
            rlo.setZ(pom.getZOff());
        }
    }

    public static RenderCallback createDrawListener(BiPredicate<Renderable, Boolean> method)
    {
        return new RenderCallback()
        {
            @Override
            public boolean addEntity(Renderable renderable, boolean ui)
            {
                return method.test(renderable, ui);
            }
        };
    }

}

